def pdf_text(path):
    try:
        raw = open(path, "rb").read().decode("latin-1")
    except Exception:
        return ""
    return " ".join(re.findall(r"\((.*?)\) Tj", raw))

def read_any(path):
    ext = path.rsplit(".", 1)[-1].lower()
    try:
        if ext == "pdf":
            return pdf_text(path)
        with open(path, encoding="utf-8", errors="replace") as f:
            return f.read()
    except Exception as e:
        return f"<ERR {e}>"

rows = []
for path in sorted(glob.glob(os.path.join(ROOT, "*", "*"))):
    base = os.path.basename(path)
    if base.endswith(".xlsx"):
        continue
    t = read_any(path)
    def g(pat, flags=re.I | re.S):
        m = re.search(pat, t, flags)
        return m.group(1).strip() if m else ""
    # subject: first heading or title line
    subj = ""
    if ext := None: pass
    m = re.search(r"<h1>(.*?)</h1>", t)
    if m: subj = m.group(1)
    if not subj:
        m = re.search(r"^# (.+)$", t, re.M)
        if m: subj = m.group(1)
    if not subj:
        # txt: second non-empty line after RESTRICTED header
        lines = [l.strip() for l in t.splitlines() if l.strip()]
        subj = lines[1] if len(lines) > 1 and lines[0].isupper() else ""
    if not subj:
        m = re.search(r'"subject",\s*"[^"]*"|subject,\s*([^,\n]+)', t)
        if m: subj = m.group(1)
    if not subj:
        m = re.search(r"<subject>(.*?)</subject>", t, re.S)
        if m: subj = m.group(1)
    # native record body
    body = ""
    m = re.search(r'"body":\s*"(.*?)"', t)
    if m: body = m.group(1)
    if not body:
        m = re.search(r"<native-record>(.*?)</native-record>", t, re.S)
        if m: body = m.group(1)
    if not body:
        m = re.search(r"## Native record\s*\n\s*(.+?)\n\s*\n", t, re.S)
        if m: body = m.group(1)
    if not body:
        m = re.search(r"NATIVE RECORD\s*\n\s*(.+?)\n\s*\n", t, re.S)
        if m: body = m.group(1)
    if not body:
        m = re.search(r"<section heading=\"Native record\">(.*?)</section>", t, re.S)
        if m: body = m.group(1)
    if not body and "pdf" == ext:
        m = re.search(r"NATIVE RECORD (.{20,400}?)(?:SOURCE LINEAGE|RELANCE|RELIANCE)", t, re.S)
        if m: body = " ".join(m.group(1).split())
    # portfolio key, role, entity, revisions
    pk = g(r"CBP-\d+-\d+") or g(r"Portfolio key<\/dt><dd>([^<]+)")
    role = g(r"identity_crosswalk|operative_authority|current_operations|approval_and_capacity|correspondence|financial_or_population_support|chronology_and_custody|independent_counterrecord")
    ent = g(r"ENT-\d+-\d+")
    rev = re.findall(r"REV-\d{4}\.\d+", t)
