import re, os, glob, zipfile, json

ROOT = "/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_9"
ROLES = ["identity_crosswalk","operative_authority","current_operations","approval_and_capacity",
         "correspondence","financial_or_population_support","chronology_and_custody","independent_counterrecord"]

def pdf_text(path):
    raw = open(path, "rb").read().decode("latin-1")
    return " ".join(re.findall(r"\((.*?)\) Tj", raw))

def read_any(path):
    ext = path.rsplit(".",1)[-1].lower()
    if ext == "pdf": return pdf_text(path)
    return open(path, encoding="utf-8", errors="replace").read()

rows = []
for path in sorted(glob.glob(os.path.join(ROOT, "*", "*"))):
    if path.endswith(".xlsx"): continue
    base = os.path.basename(path)
    t = read_any(path)
    def g0(pat, flags=re.I|re.S):
        m = re.search(pat, t, flags)
        return m.group(1).strip() if m else ""
    ext = base.rsplit(".",1)[-1].lower()
    subj = ""
    if ext == "html":
        m = re.search(r"<h1>(.*?)</h1>", t, re.S); subj = m.group(1) if m else ""
    elif ext == "md":
        m = re.search(r"^# (.+)$", t, re.M); subj = m.group(1).split(" — ")[0].strip() if m else ""
    elif ext == "txt":
        lines = [l.strip() for l in t.splitlines() if l.strip()]
        subj = lines[1] if len(lines) > 2 else ""
    elif ext == "eml":
        m = re.search(r"Subject: CB-MA-2401 — (.+?) source export", t); subj = m.group(1) if m else ""
    elif ext == "csv":
        subj = g0(r"metadata,\d{4}-\d\d-\d\d,subject,([^,]+),")
    elif ext == "json":
        subj = g0(r'"subject":\s*"([^"]+)"')
    elif ext == "xml":
        m = re.search(r"<subject>(.*?)</subject>", t, re.S); subj = m.group(1).strip() if m else ""
    elif ext == "pdf":
        m = re.search(r"^([A-Z][A-Z \-]{4,40}?)(?: RECORD| Source Export)", t); subj = m.group(1).strip().lower() if m else ""
    body = g0(r'"body":\s*"(.*?)"') \
        or g0(r"<native-record>(.*?)</native-record>") \
        or g0(r"## Native record\s*\n\s*(.+?)\n\s*\n") \
        or g0(r"NATIVE RECORD\s*\n\s*(.+?)\n\s*\n") \
        or g0(r'<section heading="Native record">(.*?)</section>') \
        or g0(r"NATIVE RECORD\s+(.{20,400}?)\s+(?:SOURCE LINEAGE|RELIANCE)")
    pk = g0(r"(CBP-\d+-\d+)")
    ent = g0(r"(ENT-\d+-\d+)")
    role = next((r for r in ROLES if r in t), "")
    revs = sorted(set(re.findall(r"REV-\d{4}\.\d+", t)))
    score = g0(r"impact-control score (\d+)")
    recid = g0(r"(CB-DOC-\d+-\d+)")
    rows.append(dict(file=base, recid=recid, subject=subj.lower(), pk=pk, role=role, entity=ent, revs=revs, score=score, body=" ".join(body.split())))

print(f"parsed {len(rows)} records")
pk_subj = {}
for r in rows: pk_subj.setdefault(r["pk"], set()).add(r["subject"])
print("\n== portfolio key -> subject ==")
for pk in sorted(pk_subj): print(f"  {pk}: {sorted(pk_subj[pk])}")
json.dump(rows, open("/tmp/records.json","w"))
"}

