import zipfile, re
from xml.etree import ElementTree as ET

path = "/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_9/12_financials/097_helios_forge_impact_population.xlsx"
z = zipfile.ZipFile(path)
print("parts:", z.namelist())

NS = {"m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}

def colnum(ref):
    m = re.match(r"([A-Z]+)", ref)
    n = 0
    for ch in m.group(1): n = n*26 + ord(ch)-64
    return n

shared = []
if "xl/sharedStrings.xml" in z.namelist():
    root = ET.fromstring(z.read("xl/sharedStrings.xml"))
    for si in root.findall("m:si", NS):
        shared.append("".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t")))

for name in z.namelist():
    if not re.match(r"xl/worksheets/sheet\d+\.xml", name): continue
    print(f"\n===== {name} =====")
    root = ET.fromstring(z.read(name))
    for row in root.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row"):
        cells = {}
        for c in row.findall("m:c", NS):
            v = c.find("m:v", NS)
            val = v.text if v is not None else ""
            if c.get("t") == "s" and val != "": val = shared[int(val)]
            elif c.get("t") == "inlineStr":
                is_el = c.find("m:is", NS)
                val = "".join(t.text or "" for t in is_el.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t")) if is_el is not None else ""
            cells[colnum(c.get("r"))] = val
        if cells:
            print(" | ".join(cells.get(i, "") for i in range(1, max(cells)+1)))
